import React, { useState, useMemo } from 'react';

function PropertyList({ properties, handleDeleteProperty, handleEditProperty, onOpenCalculator }) {
    const [page, setPage] = useState(1);
    const perPage = 6;
    const [sortKey, setSortKey] = useState('price');
    const [sortDir, setSortDir] = useState('asc');

    const sorted = useMemo(() => {
        const copy = [...properties];
        copy.sort((a,b) => {
            const av = a[sortKey] ?? 0;
            const bv = b[sortKey] ?? 0;
            if (av < bv) return sortDir === 'asc' ? -1 : 1;
            if (av > bv) return sortDir === 'asc' ? 1 : -1;
            return 0;
        });
        return copy;
    }, [properties, sortKey, sortDir]);

    const total = sorted.length;
    const pages = Math.max(1, Math.ceil(total / perPage));
    const visible = sorted.slice((page-1)*perPage, page*perPage);

    const shareProperty = (prop) => {
        const text = `فرصة عقارية مميزة! 🏠\n*${prop.type} ${prop.status}*\n📍 الموقع: ${prop.location?.city} - ${prop.location?.neighborhood || ''}\n💰 السعر: ${prop.price?.toLocaleString()} جنيه\n📏 المساحة: ${prop.area} م²\n\nللتواصل: ${prop.ownerPhone}`;
        const url = `https://wa.me/?text=${encodeURIComponent(text)}`;
        window.open(url, '_blank');
    };

    const copyDetails = (prop) => {
        const text = `نوع العقار: ${prop.type}\nالحالة: ${prop.status}\nالموقع: ${prop.location?.city}\nالسعر: ${prop.price?.toLocaleString()} جنيه\nالتفاصيل: ${prop.description}\nرقم المالك: ${prop.ownerPhone}`;
        navigator.clipboard.writeText(text);
        alert('تم نسخ تفاصيل العقار للحافظة! 📋');
    };

    return (
        <div>
            <h2 className="mb-4">📦 المخزون العقاري</h2>

            <div className="d-flex align-items-center mb-3">
                <div className="me-3">
                    <label className="form-label me-2 small">ترتيب:</label>
                    <select className="form-select form-select-sm d-inline-block" style={{width:160}} value={sortKey} onChange={e => setSortKey(e.target.value)}>
                        <option value="price">السعر</option>
                        <option value="area">المساحة</option>
                        <option value="rooms">الغرف</option>
                    </select>
                    <button className="btn btn-sm btn-outline-secondary ms-2" onClick={() => setSortDir(d => d === 'asc' ? 'desc' : 'asc')}>{sortDir === 'asc' ? '↑' : '↓'}</button>
                </div>

                <div className="ms-auto small text-muted">{total} عقار · صفحة {page} من {pages}</div>
            </div>

            <div className="row">
                {visible.map(prop => (
                    <div key={prop.id} className="col-md-6 col-lg-4 mb-4">
                        <div className="card h-100 shadow-sm">
                            <div className="position-relative">
                                <img src={(prop.images && prop.images[0]) || prop.imageUrl} className="card-img-top" alt={`صورة لـ ${prop.type}`} />
                                <div className="position-absolute" style={{top:10,right:10}}>
                                    <span className="badge bg-primary fw-bold">{prop.price?.toLocaleString?.() ?? prop.price} ج</span>
                                </div>
                            </div>
                            <div className="card-body d-flex flex-column">
                                <h5 className="card-title">{prop.type} {prop.status} في {prop.location?.neighborhood || prop.location?.city}</h5>
                                <h6 className="card-subtitle mb-2 text-muted">{prop.location?.city || ''}, {prop.location?.governorate || ''}</h6>
                                <p className="card-text">{prop.description}</p>
                                <ul className="list-group list-group-flush mt-auto">
                                    <li className="list-group-item">📏 المساحة: {prop.area} م²</li>
                                    <li className="list-group-item">🛋️ الغرف: {prop.rooms} | 🛁 الحمامات: {prop.bathrooms}</li>
                                    <li className="list-group-item fw-bold">💰 السعر: {prop.price?.toLocaleString?.()} جنيه</li>
                                    <li className="list-group-item d-flex align-items-center">
                                        <img src={prop.ownerPhoto || 'https://via.placeholder.com/80x80.png?text=مالك'} alt={`مالك ${prop.ownerName}`} style={{width:48,height:48,objectFit:'cover',borderRadius:'50%'}} className="me-3" />
                                        <div>
                                            <div>{prop.ownerName}</div>
                                            <div className="small text-muted">{prop.ownerPhone}</div>
                                        </div>
                                    </li>
                                </ul>
                            </div>
                            <div className="card-footer d-flex justify-content-between align-items-center">
                                <small className={prop.availability === 'متاحة' ? 'text-success fw-bold' : 'text-danger fw-bold'}>
                                    {prop.availability === 'متاحة' ? '✅ متاحة' : '❌ محجوزة'}
                                </small>
                                <div>
                                    <button type="button" className="btn btn-sm btn-success me-1" onClick={() => shareProperty(prop)} title="مشاركة واتساب">📱</button>
                                    <button type="button" className="btn btn-sm btn-secondary me-1" onClick={() => copyDetails(prop)} title="نسخ التفاصيل">📋</button>
                                    <button type="button" className="btn btn-sm btn-outline-dark me-2" onClick={() => onOpenCalculator(prop.price)} title="حساب القسط">🧮</button>
                                    <button type="button" className="btn btn-sm btn-info me-2" data-bs-toggle="modal" data-bs-target="#newPropertyModal" onClick={() => { handleEditProperty(prop) }}>تعديل</button>
                                    <button type="button" className="btn btn-sm btn-danger" onClick={() => handleDeleteProperty(prop.id, `${prop.type} في ${prop.location?.city || ''}`)}>حذف</button>
                                </div>
                            </div>
                        </div>
                    </div>
                ))}
            </div>

            <div className="d-flex justify-content-between align-items-center">
                <div>
                    <button className="btn btn-sm btn-outline-secondary me-2" disabled={page<=1} onClick={() => setPage(p=>Math.max(1,p-1))}>السابق</button>
                    <button className="btn btn-sm btn-outline-secondary" disabled={page>=pages} onClick={() => setPage(p=>Math.min(pages,p+1))}>التالي</button>
                </div>
                <div className="small text-muted">عرض {visible.length} من {total}</div>
            </div>
        </div>
    );
}

export default PropertyList;
